import React,{useState,useEffect,useMemo} from 'react';
import {createRoot} from 'react-dom/client';
import {LayoutDashboard,Package,TrendingUp,Truck,GitBranch,ClipboardCheck,ChartNoAxesCombined,History,Settings,ArrowUpRight,ArrowRight,ArrowDownRight,Plus,Search,ChevronDown,ChevronRight,Check,CheckCircle2,AlertTriangle,X,Download,RefreshCw,ShieldCheck,Leaf,Menu,FlaskConical,Clock,SlidersHorizontal,Upload,FileText,Lock,Info,Play,MoreHorizontal,CheckCheck,LogOut} from 'lucide-react';
import type {State,Need,Plan,Audit,Role,Scenario,Ingredient,Quote} from '../core/types';
import {eligible} from '../core/supplier';
const money=(n:number|null|undefined)=>n==null?'—':new Intl.NumberFormat('en-PK',{style:'currency',currency:'PKR',maximumFractionDigits:0}).format(n);
const num=(n:number)=>new Intl.NumberFormat('en-PK',{maximumFractionDigits:1}).format(n);
const pct=(n:number)=>`${(n*100).toFixed(1)}%`;
const scenarios:{id:Scenario;label:string;description:string}[]=[{id:'ordinary',label:'Everyday purchasing',description:'Routine demand, current quotes and normal capacity.'},{id:'shortage',label:'Supplier shortage',description:'Two suppliers have no chicken capacity. Reallocation is required.'},{id:'spike',label:'Demand surge',description:'A declared event increases ingredient demand by 40%.'},{id:'volatile',label:'Price movement',description:'Preferred supplier chicken and oil prices increase by 28%.'},{id:'unreliable',label:'Delivery risk',description:'A supplier falls below the delivery reliability policy.'},{id:'budget',label:'Tight budget',description:'A PKR 15,000 limit tests honest infeasibility handling.'},{id:'no-savings',label:'Preferred supplier wins',description:'Alternatives are more expensive. A zero-saving result is valid.'}];
type Workspace={state:State;needs:Need[];role:Role;revision:number;audit:Audit[];user:{name:string};restaurants:State['restaurant'][]};
const tabs=[{id:'overview',label:'Overview',icon:LayoutDashboard},{id:'inventory',label:'Inventory',icon:Package},{id:'forecast',label:'Demand forecast',icon:TrendingUp},{id:'suppliers',label:'Suppliers & quotes',icon:Truck},{id:'planner',label:'Purchase planner',icon:GitBranch},{id:'approvals',label:'Approvals',icon:ClipboardCheck},{id:'impact',label:'Financial impact',icon:ChartNoAxesCombined},{id:'activity',label:'Activity log',icon:History}];
function parseCSV(text:string){const records:string[][]=[];let row:string[]=[],cell='',quoted=false;for(let j=0;j<text.length;j++){const c=text[j];if(c==='"'){if(quoted&&text[j+1]==='"'){cell+='"';j++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell.trim());cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[j+1]==='\n')j++;row.push(cell.trim());if(row.some(Boolean))records.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw new Error('CSV contains an unclosed quote');row.push(cell.trim());if(row.some(Boolean))records.push(row);const header=records.shift()||[];if(!['ingredient_id','quantity','unit','expiry'].every(h=>header.includes(h)))throw new Error('Use the stock template headers: ingredient_id, quantity, unit, expiry');return records.map(r=>Object.fromEntries(header.map((h,i)=>[h,r[i]||''])));}
function App(){
 const [restaurant,setRestaurant]=useState('margalla'),[data,setData]=useState<Workspace|null>(null),[tab,setTab]=useState('overview'),[loading,setLoading]=useState(true),[error,setError]=useState(''),[busy,setBusy]=useState(''),[toast,setToast]=useState(''),[modal,setModal]=useState<{type:string;item?:any}|null>(null),[mobile,setMobile]=useState(false),[query,setQuery]=useState(''),[range,setRange]=useState(30),[selectedIngredient,setSelectedIngredient]=useState('chicken'),[planId,setPlanId]=useState(''),[importRows,setImportRows]=useState<any[]>([]),[formError,setFormError]=useState('');
 const url=(path:string)=>`${path}${path.includes('?')?'&':'?'}restaurant=${restaurant}`;
 async function load(){try{const r=await fetch(url('/api/workspace'));const b=await r.json();if(!r.ok)throw new Error(r.status===401?'AUTH':b.error);setData(b);setError('');}catch(e:any){setError(e.message);}finally{setLoading(false);}}
 useEffect(()=>{setLoading(true);setData(null);setPlanId('');load();},[restaurant]);
 useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(t)}},[toast]);
 useEffect(()=>{setQuery('');setMobile(false);window.scrollTo(0,0)},[tab]);
 useEffect(()=>{setFormError('');setImportRows([])},[modal?.type]);
 useEffect(()=>{if(!modal)return;const previous=document.activeElement as HTMLElement|null;const dialog=document.querySelector('[role=dialog]') as HTMLElement|null;const focusable=()=>Array.from(dialog?.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled)')||[]);focusable()[0]?.focus();const trap=(e:KeyboardEvent)=>{if(e.key!=='Tab')return;const f=focusable();if(!f.length)return;if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}};document.addEventListener('keydown',trap);return()=>{document.removeEventListener('keydown',trap);previous?.focus()}},[modal?.type]);
 useEffect(()=>{const key=(e:KeyboardEvent)=>{if(e.key==='Escape')setModal(null)};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key)},[]);
 async function mutate(path:string,body:any,label='Saving',success='Saved'){setBusy(label);setFormError('');try{const r=await fetch(url(path),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const b=await r.json();if(!r.ok)throw new Error(b.error);await load();setToast(success);return b;}catch(e:any){setToast(e.message);setFormError(e.message);return null;}finally{setBusy('');}}
 async function generate(){const r=await mutate('/api/plans',{},'Computing purchase plan','Purchase plan computed');if(r){setPlanId(r.plan.id);setTab('planner');}}
 async function submit(e:React.FormEvent<HTMLFormElement>,path:string,convert?:(v:any)=>any){e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));const result=await mutate(path,convert?convert(values):values);if(result)setModal(null);}
 const s=data?.state;const n=data?.needs||[];const latest=s?.plans.find(p=>p.id===planId)||s?.plans[0];const current=latest?.inputVersion===s?.inputVersion;const canManage=data?.role==='owner'||data?.role==='manager';const canStock=canManage||data?.role==='storekeeper';
 const ingredient=(id:string)=>s!.ingredients.find(i=>i.id===id)!;const supplier=(id:string)=>s!.suppliers.find(x=>x.id===id)!;
 const watch=n.filter(x=>x.required>0).sort((a,b)=>a.stock/Math.max(a.forecast.daily,.01)-b.stock/Math.max(b.forecast.daily,.01));
 const stockValue=s?s.lots.reduce((v,l)=>v+l.qty*ingredient(l.ingredientId).referencePrice,0):0;
 const pending=s?.plans.filter(p=>p.status==='proposed'&&p.inputVersion===s.inputVersion&&!p.errors.length).length||0;
 const historical=s?Array.from({length:range},(_,ix)=>{const d=new Date(Date.parse(s.asOf+'T12:00:00Z')-(range-ix-1)*86400000).toISOString().slice(0,10);return{date:d,value:s.movements.filter(m=>m.date===d&&m.type==='receipt').reduce((a,m)=>a+m.qty*ingredient(m.ingredientId).referencePrice,0)}}):[];
 const historySpend=historical.reduce((a,b)=>a+b.value,0);
 const heading:Record<string,[string,string]>={overview:['A clearer view of your kitchen.','Know what you have. Buy what you need.'],inventory:['Every ingredient, accounted for.','Usable stock, expiry and replenishment in one place.'],forecast:['Plan for what comes next.','Explainable demand estimates from your consumption history.'],suppliers:['Better buying starts with context.','Compare equivalent offers, delivery terms and reliability.'],planner:['Your next purchase, considered.','A constrained buying plan. Clear reasons. Your final say.'],approvals:['You’re in control.','Review purchasing decisions and record what arrived.'],impact:['Make the value visible.','Transparent comparisons, with evidence behind every number.'],activity:['A clear record of every decision.','Changes, computations and approvals, in order.']};
 if(loading&&!data)return <div className="screen-state"><div className="brand-mark">p<span>↗</span></div><h2>Preparing your workspace</h2><p>Loading stock, quotes and purchasing history…</p><div className="loading-track"/></div>;
 if(error&&!data)return <div className="screen-state"><ShieldCheck size={40}/><h2>{error==='AUTH'?'Your purchasing workspace is private':'Unable to open workspace'}</h2><p>{error==='AUTH'?'Sign in to access your restaurant data.':error}</p>{error==='AUTH'?<a className="btn primary" href="/signin-with-chatgpt?return_to=%2F" target="_top">Sign in with ChatGPT <ArrowRight size={16}/></a>:<button className="btn primary" onClick={()=>{setLoading(true);load()}}>Try again</button>}</div>;
 if(!s||!data)return null;
 const open=(type:string,item?:any)=>setModal({type,item});
 return <div className="app-shell">
 <button className="mobile-menu" aria-label="Open navigation" onClick={()=>setMobile(!mobile)}><Menu/></button>
 {mobile&&<div className="sidebar-scrim" onClick={()=>setMobile(false)}/>}
 <aside className={`sidebar ${mobile?'open':''}`}>
  <a className="brand" href="#overview" onClick={()=>setTab('overview')}><div className="brand-mark">p<span>↗</span></div><span>procurepilot<span className="brand-dot">.</span></span></a>
  <div className="workspace-selector"><div className="workspace-icon"><Leaf size={18}/></div><div><small>YOUR RESTAURANT</small><select aria-label="Restaurant" value={restaurant} onChange={e=>setRestaurant(e.target.value)}>{data.restaurants.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></div></div>
  <div className="nav-label">WORKSPACE</div>
  <nav>{tabs.map(t=><button key={t.id} className={`nav-item ${tab===t.id?'active':''}`} onClick={()=>setTab(t.id)}><t.icon size={18}/><span>{t.label}</span>{t.id==='approvals'&&pending>0&&<span className="nav-count">{pending}</span>}</button>)}</nav>
  <div className="sidebar-bottom"><button className="demo-card" onClick={()=>open('scenario')}><div><FlaskConical size={19}/><span>Made for a test drive</span></div><p>Explore a purchasing scenario.</p><span className="demo-card-link">Open demo studio <ArrowUpRight size={15}/></span></button>
  <button className="nav-item" onClick={()=>open('settings')}><Settings size={18}/><span>Workspace settings</span></button>
  <div className="profile"><div className="avatar">{data.role==='owner'?'AO':data.role.slice(0,2).toUpperCase()}</div><div><strong>{data.role==='owner'?'Ayesha · Demo owner':data.role[0].toUpperCase()+data.role.slice(1)+' preview'}</strong><small>Role preview · synthetic workspace</small></div><button aria-label="Preview access roles" onClick={()=>open('role')}><ChevronDown size={16}/></button></div></div>
 </aside>
 <div className="main-shell"><div className="topbar"><div className="breadcrumbs">Workspace <ChevronRight size={14}/> <strong>{tabs.find(t=>t.id===tab)?.label}</strong></div><div className="topbar-right"><span className="system-state"><span/> All calculations local to this app</span><button className="icon-button" aria-label="Workspace settings" onClick={()=>open('settings')}><SlidersHorizontal size={17}/></button><div className="top-avatar">AO</div></div></div>
 <div className="demo-strip"><FlaskConical size={14}/><span><strong>Synthetic demo</strong><span className="strip-detail"> · Fictional businesses and quotes. Real calculations.</span></span><button onClick={()=>open('scenario')}>{scenarios.find(x=>x.id===s.scenario)?.label} <ChevronDown size={12}/></button></div>
 <main><header className="page-header"><div><div className="eyebrow">{s.restaurant.name.toUpperCase()} <span> / </span> {s.restaurant.location}</div><h1>{heading[tab][0]}</h1><p>{heading[tab][1]}</p></div><div className="header-actions">{tab==='inventory'?<><button className="btn" onClick={()=>open('import')} disabled={!canStock}><Upload size={15}/> Import stock</button><button className="btn primary" onClick={()=>open('stock',s.ingredients[0])} disabled={!canStock}><Plus size={16}/> Record count</button></>:<><button className="btn" onClick={()=>open('scenario')}><FlaskConical size={15}/> Scenarios</button><button className="btn primary" onClick={generate} disabled={!!busy||!canManage}><GitBranch size={16}/>{busy==='Computing purchase plan'?'Computing…':'Generate purchase plan'}</button></>}</div></header>
 {data.role!=='owner'&&<div className="notice"><Lock size={16}/>Previewing {data.role} access. Actions are checked by the server.<button onClick={()=>open('role')}>Change role</button></div>}
 {tab==='overview'&&<>
 <div className="stat-grid"><Stat label={`Purchasing activity · ${range} days`} value={money(historySpend)} icon={ChartNoAxesCombined} foot="Synthetic receipts at reference prices"/><Stat label="Inventory on hand" value={money(stockValue)} icon={Package} foot={`${s.ingredients.length} ingredients across ${new Set(s.ingredients.map(i=>i.category)).size} categories`}/><Stat label="Ingredients to replenish" value={String(watch.length).padStart(2,'0')} icon={AlertTriangle} foot={`${n.filter(x=>x.stock<x.forecast.daily).length} below one day of cover`} tone="amber"/><Stat label="Purchasing opportunity" value={latest&&current&&!latest.errors.length?money(latest.savings):'Ready to calculate'} icon={TrendingUp} foot={latest&&current?'Expected difference for latest basket':'Generate a plan to compare your basket'} tone="green"/></div>
 <div className="overview-grid"><section className="card spend-card"><div className="card-head"><div><h2>Purchasing, in perspective</h2><p>Synthetic replenishment value over time</p></div><select className="select-small" aria-label="Activity date range" value={range} onChange={e=>setRange(Number(e.target.value))}><option value={30}>Last 30 days</option><option value={7}>Last 7 days</option></select></div><div className="chart-legend"><span className="legend-dot"/> Purchase receipts <span className="chart-total">{money(historySpend)}</span></div><AreaChart data={historical.map(h=>h.value)} labels={historical.map(h=>h.date.slice(5))}/></section>
 <section className="next-card"><div className="next-top"><span className="pill light"><span/> NEXT PURCHASING WINDOW</span><GitBranch size={21}/></div><h2>Buy with a little<br/>more certainty.</h2><p>{watch.length} ingredients need attention for the next {s.horizon} days. Compare every eligible offer in one plan.</p><div className="next-facts"><div><span>Approved suppliers</span><strong>{s.suppliers.filter(x=>x.approved).length}</strong></div><div><span>Budget available</span><strong>{money(s.budget)}</strong></div></div><button className="btn cream" disabled={!!busy||!canManage} onClick={generate}>Build my purchase plan <ArrowRight size={16}/></button><small><ShieldCheck size={12}/> Nothing is ordered without your approval.</small></section></div>
 <div className="bottom-grid"><section className="card"><div className="card-head"><div><h2>Your inventory watchlist <span className="count-badge">{watch.length}</span></h2><p>The ingredients that need your attention first</p></div><button className="text-button" onClick={()=>setTab('inventory')}>View inventory <ArrowUpRight size={14}/></button></div><div className="table-scroll"><table><thead><tr><th>INGREDIENT</th><th>USABLE STOCK</th><th>COVER</th><th>STATUS</th></tr></thead><tbody>{watch.slice(0,5).map(x=>{const i=ingredient(x.ingredientId);return <tr key={i.id}><td><IngredientName i={i}/></td><td>{num(x.stock)} <span className="muted">{i.unit}</span></td><td>{num(x.stock/Math.max(.01,x.forecast.daily))} days</td><td><Badge tone={x.stock<x.forecast.daily?'amber':'gray'}>{x.stock<x.forecast.daily?'Replenish soon':'Plan restock'}</Badge></td></tr>})}</tbody></table></div><div className="table-foot"><span><Clock size={13}/> Snapshot: 8 Nov 2026 · end of day</span><button className="text-button" onClick={()=>setTab('forecast')}>Explore demand <ArrowRight size={13}/></button></div></section>
 <section className="card suppliers-mini"><div className="card-head"><div><h2>Your supplier network</h2><p>Reliability from synthetic delivery records</p></div><Truck size={19} className="muted"/></div>{s.suppliers.map((sup,ix)=><button key={sup.id} className="supplier-row" onClick={()=>{setSelectedIngredient('chicken');setTab('suppliers')}}><span className={`supplier-avatar color-${ix}`}>{sup.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><span><strong>{sup.name}</strong><small>{sup.area}</small><span className="progress-track"><i style={{width:pct(sup.onTime/sup.deliveries)}}/></span></span><b>{pct(sup.onTime/sup.deliveries)}</b></button>)}<button className="text-button network-link" onClick={()=>setTab('suppliers')}>Compare supplier offers <ArrowRight size={14}/></button></section></div>
 <div className="bottom-note"><Leaf size={15}/><span>A thoughtful purchase today. A healthier kitchen tomorrow.</span><span>ISLAMABAD / RAWALPINDI</span></div>
 </>}
 {tab==='inventory'&&<><div className="summary-band"><div><span>Inventory value</span><strong>{money(stockValue)}</strong></div><div><span>Replenishment needed</span><strong>{watch.length} ingredients</strong></div><div><span>Expiry exposure</span><strong>{n.filter(x=>x.expiring>0).length} ingredients</strong></div><div><span>Source</span><strong>Seeded stock ledger</strong></div></div><section className="card"><div className="card-head"><div><h2>Ingredient inventory</h2><p>Counts and expiry are used in every purchasing calculation.</p></div><SearchBox value={query} onChange={setQuery} placeholder="Find an ingredient"/></div><div className="table-scroll"><table><thead><tr><th>INGREDIENT</th><th>PHYSICAL STOCK</th><th>USABLE IN WINDOW</th><th>{s.horizon}-DAY DEMAND</th><th>NET NEED</th><th>EARLIEST EXPIRY</th><th/></tr></thead><tbody>{s.ingredients.filter(i=>i.name.toLowerCase().includes(query.toLowerCase())).map(i=>{const need=n.find(x=>x.ingredientId===i.id)!;const lots=s.lots.filter(l=>l.ingredientId===i.id);const physical=lots.reduce((v,l)=>v+l.qty,0);return <tr key={i.id}><td><IngredientName i={i}/></td><td>{num(physical)} {i.unit}</td><td>{num(need.stock)} {i.unit}{need.expiring>0&&<small className="amber-text">{num(need.expiring)} outside usable window</small>}</td><td>{num(need.demand)} {i.unit}</td><td><Badge tone={need.required>0?'amber':'green'}>{num(need.required)} {i.unit}</Badge></td><td>{lots.length?lots.map(l=>l.expires).sort()[0]:'No stock'}</td><td><button className="icon-button" aria-label={`Record ${i.name} count`} onClick={()=>open('stock',i)} disabled={!canStock}><Plus size={16}/></button></td></tr>})}</tbody></table></div></section><section className="card spaced"><div className="card-head"><div><h2>Recent stock movements</h2><p>Receipts, kitchen consumption, waste and count adjustments</p></div></div><div className="table-scroll"><table><thead><tr><th>DATE</th><th>INGREDIENT</th><th>MOVEMENT</th><th>QUANTITY</th><th>REFERENCE</th></tr></thead><tbody>{s.movements.slice(-12).reverse().map(m=><tr key={m.id}><td>{m.date}</td><td>{ingredient(m.ingredientId).name}</td><td><Badge tone={m.type==='receipt'?'green':m.type==='waste'?'amber':'gray'}>{m.type}</Badge></td><td>{m.qty>0?'+':''}{num(m.qty)} {ingredient(m.ingredientId).unit}</td><td className="muted truncate">{m.reference}</td></tr>)}</tbody></table></div></section></>}
 {tab==='forecast'&&<><div className="summary-band"><div><span>Planning horizon</span><strong>{s.horizon} days</strong></div><div><span>History</span><strong>90 synthetic days</strong></div><div><span>Selection method</span><strong>Rolling-origin MAE</strong></div><div><span>Declared uplift</span><strong>{s.scenario==='spike'?'+40% event':'None'}</strong></div></div><section className="card"><div className="card-head"><div><h2>Ingredient demand</h2><p>Stockout days are excluded from model fitting.</p></div><select className="select-small" value={selectedIngredient} onChange={e=>setSelectedIngredient(e.target.value)} aria-label="Forecast ingredient">{s.ingredients.map(i=><option key={i.id} value={i.id}>{i.name}</option>)}</select></div>{(()=>{const f=n.find(x=>x.ingredientId===selectedIngredient)!.forecast;return <><div className="forecast-stats"><div><span>Expected demand</span><strong>{num(f.total)} <small>{ingredient(selectedIngredient).unit}</small></strong></div><div><span>Illustrative range</span><strong>{num(f.lower)}–{num(f.upper)}</strong></div><div><span>Backtest MAE / day</span><strong>{num(f.mae)}</strong></div><div><span>Selected model</span><strong className="model-name">{f.model.replaceAll('-',' ')}</strong></div></div><AreaChart data={f.history.map(h=>h.qty)} labels={f.history.map(h=>h.date.slice(5))}/><div className="method-note"><Info size={16}/><span>The lowest MAE across weekday average, seasonal naïve and recent average wins over the last 14 eligible dates. The range uses historical error; it is an illustrative uncertainty band, not a calibrated guarantee.</span></div></>})()}</section><section className="card spaced"><div className="table-scroll"><table><thead><tr><th>INGREDIENT</th><th>MODEL</th><th>USABLE HISTORY</th><th>DAILY ESTIMATE</th><th>HORIZON TOTAL</th><th>WAPE</th></tr></thead><tbody>{n.map(x=><tr key={x.ingredientId}><td>{ingredient(x.ingredientId).name}</td><td className="muted">{x.forecast.model.replaceAll('-',' ')}</td><td>{x.forecast.observations} days</td><td>{num(x.forecast.daily)} {ingredient(x.ingredientId).unit}</td><td>{num(x.demand)} {ingredient(x.ingredientId).unit}</td><td>{x.forecast.wape===null?'Unavailable':pct(x.forecast.wape)}</td></tr>)}</tbody></table></div></section></>}
 {tab==='suppliers'&&<><div className="supplier-grid">{s.suppliers.map((sup,ix)=><section className="card supplier-detail" key={sup.id}><div className="supplier-detail-head"><span className={`supplier-avatar color-${ix}`}>{sup.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><Badge tone={sup.onTime/sup.deliveries>=s.settings.minimumReliability?'green':'amber'}>{sup.onTime/sup.deliveries>=s.settings.minimumReliability?'Eligible':'Policy warning'}</Badge></div><h2>{sup.name}</h2><p>{sup.area}</p><div className="supplier-metrics"><div><span>On-time deliveries</span><strong>{sup.onTime}/{sup.deliveries} <small>{pct(sup.onTime/sup.deliveries)}</small></strong></div><div><span>Accepted quantity</span><strong>{pct(sup.accepted/sup.received)}</strong></div><div><span>Delivery charge</span><strong>{money(sup.delivery)}</strong></div><div><span>Lead time</span><strong>{sup.leadDays} day</strong></div></div></section>)}</div><section className="card spaced"><div className="card-head"><div><h2>Compare current offers</h2><p>Equivalent approved grade · prices per base unit · synthetic quotes</p></div><select className="select-small" value={selectedIngredient} onChange={e=>setSelectedIngredient(e.target.value)} aria-label="Compare ingredient">{s.ingredients.map(i=><option key={i.id} value={i.id}>{i.name}</option>)}</select></div><div className="table-scroll"><table><thead><tr><th>SUPPLIER</th><th>UNIT PRICE</th><th>PACK</th><th>CAPACITY</th><th>VALID THROUGH</th><th>ELIGIBILITY</th><th/></tr></thead><tbody>{s.quotes.filter(q=>q.ingredientId===selectedIngredient).map(q=>{const reasons=eligible(s,q);return <tr key={q.id}><td><strong>{supplier(q.supplierId).name}</strong></td><td>{money(q.price)} / {ingredient(q.ingredientId).unit}</td><td>{q.pack} {ingredient(q.ingredientId).unit}</td><td>{q.capacity} {ingredient(q.ingredientId).unit}</td><td>{q.validUntil}</td><td><Badge tone={reasons.length?'amber':'green'}>{reasons.length?reasons[0]:'Eligible offer'}</Badge></td><td><button className="text-button" disabled={!canManage} onClick={()=>open('quote',q)}>Edit quote <ArrowUpRight size={13}/></button></td></tr>})}</tbody></table></div></section><div className="mechanism-callout"><div className="mechanism-icon"><GitBranch size={24}/></div><div><h3>Explore supplier incentives</h3><p>Run a clearly labeled, single-lot reverse second-price experiment. No supplier is contacted.</p></div><button className="btn" onClick={()=>open('auction')} disabled={!canManage}>Open mechanism lab <ArrowRight size={15}/></button></div></>}
 {tab==='planner'&&<>{!latest?<Empty icon={GitBranch} title="A better purchasing decision starts here" text="Use your current stock, forecast and supplier quotes to calculate a constrained buying plan." action={<button className="btn primary" onClick={generate} disabled={!canManage||!!busy}>Generate purchase plan <ArrowRight size={16}/></button>}/>:<>
 <div className="plan-toolbar"><div><Badge tone={latest.errors.length?'red':latest.status==='approved'||latest.status==='received'?'green':'gray'}>{latest.errors.length?'Blocked':latest.status}</Badge><span className="muted">Plan {latest.id.slice(0,8)} · {new Date(latest.createdAt).toLocaleString('en-GB')}</span>{!current&&<Badge tone="amber">Inputs changed · stale</Badge>}</div><select className="select-small" value={latest.id} onChange={e=>setPlanId(e.target.value)} aria-label="Plan history">{s.plans.map(p=><option key={p.id} value={p.id}>{p.id.slice(0,8)} · {p.status} · {money(p.cost)}</option>)}</select></div>
 {latest.errors.length>0&&<div className="notice danger"><AlertTriangle size={18}/><div><strong>This plan cannot be approved.</strong>{latest.errors.map((e,i)=><p key={i}>{e}</p>)}</div></div>}
 <div className="stat-grid plan-stats"><Stat label="Recommended landed cost" value={latest.errors.length?'No feasible plan':money(latest.cost)} icon={Package} foot={`${money(latest.deliveryCost)} delivery included`}/><Stat label="Preferred-supplier baseline" value={money(latest.baseline)} icon={Truck} foot={latest.baselineFeasible?'Same requirements and constraints':'Baseline fails current constraints'}/><Stat label="Expected basket difference" value={money(latest.savings)} icon={TrendingUp} foot="Synthetic opportunity · not realized savings" tone="green"/><Stat label="Supplier allocation" value={String(new Set(latest.lines.map(l=>l.supplierId)).size)} icon={GitBranch} foot={latest.optimal?'Integral optimum for this model':'Independently checked candidate'}/></div>
 <div className="planner-grid"><section className="card"><div className="card-head"><div><h2>Your purchasing recommendation</h2><p>Whole packs, confirmed capacity and complete delivery charges.</p></div>{latest.status==='proposed'&&<button className="text-button" onClick={()=>open('revise',latest)} disabled={!canManage||!current}>Adjust quantities <SlidersHorizontal size={14}/></button>}</div>{latest.lines.length?<div className="table-scroll"><table><thead><tr><th>INGREDIENT / SUPPLIER</th><th>QUANTITY</th><th>UNIT PRICE</th><th>PRODUCT TOTAL</th></tr></thead><tbody>{latest.lines.map((l,ix)=><tr key={ix}><td><strong>{ingredient(l.ingredientId).name}</strong><small>{supplier(l.supplierId).name}</small></td><td>{l.qty} {ingredient(l.ingredientId).unit}<small>{l.packs} packs</small></td><td>{money(l.unitPrice)}</td><td>{money(l.cost)}</td></tr>)}</tbody></table></div>:<div className="inline-empty">Resolve the constraints, then generate a fresh plan.</div>}<div className="plan-total"><span>Products <b>{money(latest.productCost)}</b></span><span>Delivery <b>{money(latest.deliveryCost)}</b></span><strong>Landed total <b>{money(latest.cost)}</b></strong></div></section>
 <section className="card approval-panel"><div className="approval-seal"><ShieldCheck size={27}/></div><h2>A recommendation.<br/>Your decision.</h2><p>Review the quantities and supplier tradeoffs. No order is sent by ProcurePilot.</p>{latest.warnings.map((w,i)=><div className="warning-line" key={i}><Info size={14}/><span>{w}</span></div>)}{latest.status==='proposed'?<><button className="btn primary full" disabled={!canManage||!current||!!latest.errors.length||!!busy} onClick={()=>open('decision',{plan:latest,decision:'approved'})}><Check size={16}/> Approve simulated plan</button><button className="btn full" disabled={!canManage||!!busy} onClick={()=>open('decision',{plan:latest,decision:'rejected'})}>Reject with feedback</button></>:<><div className="decision-note"><CheckCircle2 size={16}/>{latest.status==='rejected'?'Rejected':latest.status==='received'?'Received in demonstration':'Approved by '+latest.approvedBy}<small>{latest.decisionReason}</small></div>{['approved','received'].includes(latest.status)&&<a className="btn full" href={url('/api/plans/'+latest.id+'/export')}><Download size={15}/> Export purchase request</a>}{latest.status==='approved'&&<button className="btn primary full" disabled={!canStock} onClick={()=>open('receive',latest)}>Record simulated receipt <ArrowRight size={15}/></button>}</>}<small className="approval-foot"><Lock size={12}/> Server-enforced role and version checks</small></section></div>
 <section className="card spaced"><div className="card-head"><div><h2>Behind the recommendation</h2><p>Inspect the actual computations and policy checks.</p></div><span className="pill"><GitBranch size={13}/> {latest.traces.length} agents</span></div><div className="agent-list">{latest.traces.map((t,ix)=><details key={ix} className="agent-item"><summary><span className={`agent-index ${t.status}`}>{t.status==='blocked'?<X size={15}/>:t.status==='warning'?<AlertTriangle size={14}/>:<Check size={15}/>}</span><span><strong>{t.agent} agent</strong><small>{t.summary}</small></span><Badge tone={t.status==='blocked'?'red':t.status==='warning'?'amber':'green'}>{t.status}</Badge><ChevronDown size={15}/></summary><div className="agent-details">{t.details.length?t.details.map((d,i)=><p key={i}>{d}</p>):<p>No exclusions.</p>}</div></details>)}</div><div className="method-note"><Info size={16}/><span>{latest.baselineMethod} This purchasing difference is a synthetic scenario result, not a claim of customer savings.</span></div></section></> }</>}
 {tab==='approvals'&&<><div className="summary-band"><div><span>Awaiting review</span><strong>{pending} current plans</strong></div><div><span>Approved</span><strong>{s.plans.filter(p=>p.status==='approved').length}</strong></div><div><span>Received</span><strong>{s.receipts.length}</strong></div><div><span>Control</span><strong>Human approval required</strong></div></div>{!s.plans.length?<Empty icon={ClipboardCheck} title="No purchasing decisions yet" text="Generate a plan to inspect risk checks and exercise the approval workflow." action={<button className="btn primary" onClick={generate} disabled={!canManage}>Generate a plan</button>}/>:<section className="card"><div className="card-head"><div><h2>Purchasing decisions</h2><p>Only current, validated plans can be approved.</p></div></div><div className="table-scroll"><table><thead><tr><th>PLAN</th><th>CREATED</th><th>LANDED COST</th><th>STATUS</th><th>INPUTS</th><th/></tr></thead><tbody>{s.plans.map(p=><tr key={p.id}><td><strong>{p.id.slice(0,8)}</strong><small>{scenarios.find(x=>x.id===p.scenario)?.label}</small></td><td>{new Date(p.createdAt).toLocaleDateString('en-GB')}</td><td>{p.errors.length?'Infeasible':money(p.cost)}</td><td><Badge tone={p.status==='rejected'?'red':p.status==='proposed'?'amber':'green'}>{p.status}</Badge></td><td>{p.inputVersion===s.inputVersion?'Current':'Historical / stale'}</td><td><button className="text-button" onClick={()=>{setPlanId(p.id);setTab('planner')}}>Review <ArrowUpRight size={14}/></button></td></tr>)}</tbody></table></div></section>}</>}
 {tab==='impact'&&<>{(()=>{const gross=s.receipts.reduce((v,r)=>v+(r.priceVariance||0),0);const net=gross-s.fee;const opportunities=latest&&current&&!latest.errors.length?latest.savings:null;return <><div className="stat-grid"><Stat label="Latest basket opportunity" value={money(opportunities)} icon={TrendingUp} foot="Expected difference · current inputs only" tone="green"/><Stat label="Recorded purchase variance" value={money(gross)} icon={FileText} foot={`${s.receipts.length} synthetic receipts · reference comparison`}/><Stat label="Illustrative monthly fee" value={money(s.fee)} icon={ChartNoAxesCombined} foot="Pricing hypothesis · adjustable in settings"/><Stat label="Period net comparison" value={money(net)} icon={ArrowUpRight} foot="Recorded variance less one monthly fee" tone={net>=0?'green':'amber'}/></div><div className="impact-grid"><section className="card"><div className="card-head"><div><h2>Follow the money</h2><p>Only recorded receipts enter this comparison.</p></div></div><div className="waterfall"><div><span>Comparable reference baskets</span><strong>{money(s.receipts.reduce((v,r)=>v+(r.baseline||0),0))}</strong></div><div><span>Invoices for comparable receipts</span><strong>− {money(s.receipts.filter(r=>r.baseline!==null).reduce((v,r)=>v+r.cost,0))}</strong></div><div className="positive"><span>Recorded price variance</span><strong>{money(gross)}</strong></div><div><span>One illustrative monthly subscription</span><strong>− {money(s.fee)}</strong></div><div className="net"><span>Net comparison</span><strong>{money(net)}</strong></div></div><div className="method-note"><Info size={16}/><span>This includes synthetic receipts recorded in this workspace session history, not a validated monthly customer outcome. No waste, time or emergency-purchase benefits are added. Avoided losses are not inferred.</span></div></section><section className="value-card"><Leaf size={28}/><h2>Value you can<br/>explain.</h2><p>Purchasing difference = admissible baseline − invoice cost.</p><p>Net comparison = recorded purchasing difference − subscription.</p><div className="value-formula"><span>Illustrative fee coverage</span><strong>{s.fee?pct(gross/s.fee):'Fee is zero'}</strong></div><button className="btn" onClick={()=>open('settings')}>Adjust fee assumption <SlidersHorizontal size={14}/></button></section></div><section className="card spaced"><div className="card-head"><div><h2>Outcome evidence</h2><p>Full simulated receipts and recorded invoice assumptions</p></div></div>{s.receipts.length?<div className="table-scroll"><table><thead><tr><th>PLAN</th><th>REFERENCE</th><th>INVOICE</th><th>VARIANCE</th><th>EVIDENCE</th></tr></thead><tbody>{s.receipts.map(r=><tr key={r.id}><td>{r.planId.slice(0,8)}</td><td>{money(r.baseline)}</td><td>{money(r.cost)}</td><td>{money(r.priceVariance)}</td><td><Badge>Synthetic receipt</Badge></td></tr>)}</tbody></table></div>:<div className="inline-empty">Approve a plan and record a simulated receipt to populate outcome evidence.</div>}</section></>})()}</>}
 {tab==='activity'&&<section className="card"><div className="card-head"><div><h2>Workspace audit trail</h2><p>Server-recorded actions · latest 100 events · retained across demo resets</p></div>{data.role==='owner'&&<a className="btn" href={url('/api/backup')}><Download size={15}/> Export workspace</a>}</div>{data.audit.length?<div className="audit-list">{data.audit.map(a=><div className="audit-row" key={a.id}><span className="audit-icon"><CheckCheck size={17}/></span><div><strong>{a.action.toLowerCase().replaceAll('_',' ')}</strong><p>{a.detail}</p><small>{a.actor} · {new Date(a.at).toLocaleString('en-GB')}</small></div></div>)}</div>:<Empty icon={History} title="Your workspace is ready" text="Generate a purchase plan, edit a quote or record a stock count. Each change will appear here."/>}</section>}
 </main><footer className="app-footer"><span>procurepilot<span className="brand-dot">.</span> <span className="footer-divider">/</span> Purchasing, with perspective.</span><span><ShieldCheck size={12}/> Human decisions. Traceable calculations.</span></footer></div>
 {toast&&<div className="toast" role="status"><Info size={17}/><span>{toast}</span><button aria-label="Dismiss notification" onClick={()=>setToast('')}><X size={15}/></button></div>}
 {busy&&<div className="working-indicator" role="status"><RefreshCw size={13} className="spin"/>{busy}</div>}
 {modal&&<div className="modal-overlay" onClick={e=>{if(e.target===e.currentTarget)setModal(null)}}><section role="dialog" aria-modal="true" aria-labelledby="modal-title" className={`modal ${['scenario','revise','auction'].includes(modal.type)?'wide':''}`}><button className="modal-close icon-button" aria-label="Close dialog" onClick={()=>setModal(null)}><X size={19}/></button>
 {modal.type==='scenario'&&<><div className="eyebrow">DEMO STUDIO</div><h2 id="modal-title">A different day in the kitchen.</h2><p className="modal-intro">Load a synthetic scenario, then generate a new plan. Stock and quotes reset; prior plans remain in history.</p><div className="scenario-grid">{scenarios.map((sc,ix)=><button key={sc.id} disabled={!canManage||!!busy} className={`scenario-tile ${s.scenario===sc.id?'selected':''}`} onClick={async()=>{const r=await mutate('/api/scenario',{scenario:sc.id},'Loading scenario','Scenario loaded. Generate a plan to see the effect.');if(r)setModal(null)}}><span className="scenario-number">0{ix+1}</span><strong>{sc.label}</strong><p>{sc.description}</p><span>{s.scenario===sc.id?'Current scenario':'Explore scenario'} <ArrowUpRight size={13}/></span></button>)}</div></>}
 {modal.type==='stock'&&<><div className="eyebrow">INVENTORY COUNT</div><h2 id="modal-title">Record what’s on hand.</h2><p className="modal-intro">This replaces the selected ingredient’s lot balance and records the difference as a count adjustment.</p><form onSubmit={e=>submit(e,'/api/stock')}><label>Ingredient<select name="ingredientId" defaultValue={modal.item.id}>{s.ingredients.map(i=><option key={i.id} value={i.id}>{i.name} · {i.unit}</option>)}</select></label><div className="form-grid"><label>Physical quantity<input name="qty" type="number" min="0" step="0.01" required defaultValue={s.lots.filter(l=>l.ingredientId===modal.item.id).reduce((v,l)=>v+l.qty,0)}/></label><label>Expiry date<input name="expires" type="date" min={s.asOf} defaultValue="2026-11-12" required/></label></div><label>Reason<input name="reason" required maxLength={160} placeholder="e.g. End-of-day physical count"/></label><FormError error={formError}/><button className="btn primary full" disabled={!!busy}>Save stock count <Check size={15}/></button></form></>}
 {modal.type==='quote'&&<><div className="eyebrow">SUPPLIER OFFER</div><h2 id="modal-title">Update the comparison.</h2><p className="modal-intro">{supplier(modal.item.supplierId).name} · {ingredient(modal.item.ingredientId).name}. Updating a quote makes existing plans stale.</p><form onSubmit={e=>submit(e,'/api/quote')}><input type="hidden" name="id" value={modal.item.id}/><label>Price per {ingredient(modal.item.ingredientId).unit} · PKR<input name="price" type="number" min="0.01" step="0.01" required defaultValue={modal.item.price}/></label><div className="form-grid"><label>Available capacity<input name="capacity" type="number" min="0" step="0.01" required defaultValue={modal.item.capacity}/></label><label>Valid through<input name="validUntil" type="date" min={s.asOf} defaultValue={modal.item.validUntil} required/></label></div><FormError error={formError}/><button className="btn primary full" disabled={!!busy}>Save synthetic quote <Check size={15}/></button></form></>}
 {modal.type==='settings'&&<><div className="eyebrow">WORKSPACE POLICY</div><h2 id="modal-title">Your purchasing guardrails.</h2><p className="modal-intro">All values apply to the fictional {s.restaurant.name} workspace.</p><form onSubmit={e=>submit(e,'/api/settings')}><label>Purchasing budget · PKR<input name="budget" type="number" min="1" required defaultValue={s.budget}/></label><div className="form-grid"><label>Planning horizon<select name="horizon" defaultValue={s.horizon}>{[1,2,3,4].map(x=><option key={x} value={x}>{x} days</option>)}</select></label><label>Monthly fee assumption · PKR<input name="fee" type="number" min="0" required defaultValue={s.fee}/></label></div><FormError error={formError}/><button className="btn primary full" disabled={!canManage||!!busy}>Save policy</button></form><div className="settings-extra"><button className="text-button" onClick={()=>open('role')}>Preview access roles <Lock size={14}/></button>{data.role==='owner'&&<><a className="text-button" href={url('/api/backup')}>Download synthetic backup <Download size={14}/></a><button className="text-button red-text" onClick={()=>open('reset')}>Reset demonstration data <RefreshCw size={14}/></button></>}<a className="text-button" href={url('/api/source')}>Download application source <Download size={14}/></a><a className="text-button" href="/signout-with-chatgpt?return_to=%2F" target="_top">Sign out <LogOut size={14}/></a></div></>}
 {modal.type==='role'&&<><div className="eyebrow">ACCESS PREVIEW</div><h2 id="modal-title">Try a different perspective.</h2><p className="modal-intro">As workspace owner, preview restricted roles. Permissions are enforced on the server. This does not invite or authenticate another person.</p><div className="role-list">{(['owner','manager','storekeeper','viewer'] as Role[]).map(role=><button key={role} disabled={!!busy} onClick={async()=>{const r=await mutate('/api/role',{role});if(r)setModal(null)}}><span><strong>{role}</strong><small>{role==='owner'?'All actions, backups and resets':role==='manager'?'Plan, quote and approve':role==='storekeeper'?'Stock counts, imports and receiving':'Read-only workspace access'}</small></span>{data.role===role?<CheckCircle2 size={20}/>:<ChevronRight size={17}/>}</button>)}</div></>}
 {modal.type==='decision'&&<><div className="eyebrow">MANAGER DECISION</div><h2 id="modal-title">{modal.item.decision==='approved'?'Approve this simulated plan?':'Record your feedback.'}</h2><p className="modal-intro">Plan {modal.item.plan.id.slice(0,8)} · {money(modal.item.plan.cost)}. Approval records your decision. No supplier receives a message.</p><form onSubmit={e=>submit(e,'/api/plans/'+modal.item.plan.id+'/decision',v=>({...v,decision:modal.item.decision}))}><label>Decision reason<textarea name="reason" required maxLength={240} placeholder="Quantities and delivery terms reviewed."/></label><FormError error={formError}/><button className="btn primary full" disabled={!!busy}>{modal.item.decision==='approved'?'Approve simulated plan':'Reject plan'} <Check size={15}/></button></form></>}
 {modal.type==='receive'&&<><div className="eyebrow">SIMULATED RECEIVING</div><h2 id="modal-title">Close the purchasing loop.</h2><p className="modal-intro">Record a full, accepted synthetic delivery. Stock is updated once and an invoice comparison is added to Financial impact.</p><form onSubmit={e=>submit(e,'/api/plans/'+modal.item.id+'/receive',v=>({...v,confirm:true}))}><label>Invoice product-price factor<input name="priceFactor" type="number" min="0.5" max="1.5" step="0.01" defaultValue="1" required/></label><p className="field-help">1.00 uses quoted product prices. 1.05 records a 5% invoice increase. Delivery charges are unchanged. Partial receipts and quality rejections require a future extension.</p><FormError error={formError}/><button className="btn primary full" disabled={!!busy}>Confirm full simulated receipt <Check size={15}/></button></form></>}
 {modal.type==='reset'&&<><div className="eyebrow">DEMO RESET</div><h2 id="modal-title">Start this test drive again?</h2><p className="modal-intro">This deletes this restaurant’s synthetic plans, receipts, edits and experiments. Other restaurant workspaces and the audit trail are retained.</p><button className="btn primary full" disabled={!!busy} onClick={async()=>{const r=await mutate('/api/reset',{confirm:'RESET SYNTHETIC DATA'});if(r){setPlanId('');setModal(null)}}}>Reset synthetic workspace <RefreshCw size={15}/></button></>}
 {modal.type==='import'&&<><div className="eyebrow">STOCK IMPORT</div><h2 id="modal-title">Bring your counts together.</h2><p className="modal-intro">CSV counts are validated before a single atomic commit. Duplicate ingredients, unknown units and invalid dates are rejected.</p><a className="btn full" href={url('/api/template')}><Download size={15}/> Download stock template</a><label className="upload-zone"><Upload size={25}/><strong>Choose a stock CSV</strong><span>Up to 100 rows · 1 MB maximum</span><input type="file" accept=".csv,text/csv" onChange={async e=>{setFormError('');setImportRows([]);try{const f=e.target.files?.[0];if(!f)return;if(f.size>1000000)throw new Error('Maximum file size is 1 MB');const rows=parseCSV(await f.text());const r=await mutate('/api/import',{rows,preview:true},'Validating CSV','CSV validated');if(r)setImportRows(rows);}catch(e:any){setFormError(e.message)}}}/></label>{importRows.length>0&&<div className="notice"><CheckCircle2 size={16}/>{importRows.length} valid stock counts ready to commit.</div>}<FormError error={formError}/><button className="btn primary full" disabled={!importRows.length||!!busy} onClick={async()=>{const r=await mutate('/api/import',{rows:importRows});if(r)setModal(null)}}>Import validated counts <Check size={15}/></button></>}
 {modal.type==='revise'&&<><div className="eyebrow">MANAGER REVISION</div><h2 id="modal-title">Make the plan your own.</h2><p className="modal-intro">Change whole-pack quantities. A new version is created and every constraint is checked again. Invalid revisions cannot be approved.</p><form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);mutate('/api/plans/'+modal.item.id+'/revise',{lines:modal.item.lines.map((l:any,ix:number)=>({...l,packs:Number(f.get('packs_'+ix))}))},'Validating revision','New plan version created').then(r=>{if(r){setPlanId(r.plan.id);setModal(null)}})}}><div className="revision-list">{modal.item.lines.map((l:any,ix:number)=><label key={ix}><span><strong>{ingredient(l.ingredientId).name}</strong><small>{supplier(l.supplierId).name} · {s.quotes.find(q=>q.ingredientId===l.ingredientId&&q.supplierId===l.supplierId)!.pack} {ingredient(l.ingredientId).unit}/pack</small></span><input name={'packs_'+ix} type="number" min="0" step="1" defaultValue={l.packs} required/></label>)}</div><FormError error={formError}/><button className="btn primary full" disabled={!!busy}>Create checked revision <Check size={15}/></button></form></>}
 {modal.type==='auction'&&<><div className="eyebrow">MECHANISM LAB · SYNTHETIC EXPERIMENT</div><h2 id="modal-title">What changes when incentives change?</h2><p className="modal-intro">One standardized indivisible lot. Synthetic private costs are 88% of quoted product cost. Under the experiment’s truthful-bid assumption, the lowest bidder wins and receives the second-lowest bid.</p><form className="auction-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);mutate('/api/auction',Object.fromEntries(f),'Running mechanism experiment','Experiment computed')}}><label>Ingredient<select name="ingredientId" defaultValue="chicken">{s.ingredients.map(i=><option key={i.id} value={i.id}>{i.name} · {i.unit}</option>)}</select></label><label>Lot quantity<input name="qty" type="number" min="1" defaultValue="10" required/></label><button className="btn primary" disabled={!!busy}><Play size={15}/> Run experiment</button></form>{s.bidRounds[0]&&(()=>{const r=s.bidRounds[0];return <div className="auction-result"><h3>Latest experiment · {ingredient(r.ingredientId).name}, {r.qty} {ingredient(r.ingredientId).unit}</h3><div className="table-scroll"><table><thead><tr><th>SUPPLIER</th><th>PRIVATE COST / BID</th><th>RESULT</th></tr></thead><tbody>{r.privateCosts.map(b=><tr key={b.supplierId}><td>{supplier(b.supplierId).name}</td><td>{money(b.bid)}</td><td>{b.supplierId===r.winner?<Badge tone="green">Winner</Badge>:'—'}</td></tr>)}</tbody></table></div><div className="auction-numbers"><div><span>Pay-as-bid comparator</span><strong>{money(r.firstPrice)}</strong></div><div><span>Second-price payment</span><strong>{money(r.payment)}</strong></div><div><span>Winner utility</span><strong>{money(r.winnerUtility)}</strong></div></div></div>})()}<div className="method-note"><Info size={16}/><span>No real supplier participation or bargaining occurred. The pay-as-bid comparator reuses the same assumed bids; it is not an equilibrium prediction. Delivery fees, multi-item allocation and quality strategy are excluded. This experiment does not claim procurement savings or universal truthful behavior.</span></div></>}
 </section></div>}
 </div>
}
function Stat({label,value,icon:Icon,foot,tone='gray'}:{label:string;value:string;icon:any;foot:string;tone?:string}){return <section className={`stat-card ${tone}`}><div><span>{label}</span><Icon size={17}/></div><strong>{value}</strong><p>{tone==='green'?<ArrowUpRight size={13}/>:tone==='amber'?<span className="tiny-dot amber"/>:<span className="tiny-dot"/>}{foot}</p></section>}
function Badge({children,tone='gray'}:{children:React.ReactNode;tone?:string}){return <span className={`badge ${tone}`}><span/>{children}</span>}
function IngredientName({i}:{i:Ingredient}){const initial:Record<string,string>={Protein:'Pr',Dairy:'Da',Produce:'Ve','Dry goods':'Gr',Pantry:'Pa',Beverages:'Co'};return <div className="ingredient-name"><span className={'ingredient-icon '+i.category.toLowerCase().replaceAll(' ','-')}>{initial[i.category]}</span><span><strong>{i.name}</strong><small>{i.category}</small></span></div>}
function SearchBox({value,onChange,placeholder}:{value:string;onChange:(s:string)=>void;placeholder:string}){return <div className="search-box"><Search size={15}/><input value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} aria-label={placeholder}/></div>}
function Empty({icon:Icon,title,text,action}:{icon:any;title:string;text:string;action?:React.ReactNode}){return <div className="empty-state card"><span><Icon size={30}/></span><h2>{title}</h2><p>{text}</p>{action}</div>}
function FormError({error}:{error:string}){return error?<div className="form-error" role="alert"><AlertTriangle size={15}/>{error}</div>:null;}
function AreaChart({data,labels}:{data:number[];labels:string[]}){const [hover,setHover]=useState<number|null>(null);const max=Math.max(...data,1)*1.15,w=760,h=205,left=58,bottom=26,top=15;const x=(i:number)=>left+i*(w-left-12)/Math.max(1,data.length-1),y=(v:number)=>h-bottom-v/max*(h-top-bottom);const line=data.map((v,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ');const area=`${line} L${x(data.length-1)},${h-bottom} L${left},${h-bottom} Z`;return <div className="chart-wrap"><svg viewBox={`0 0 ${w} ${h}`} role="img" aria-label={`Time series: ${data.length} daily observations`} onMouseLeave={()=>setHover(null)}><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#7c9f88" stopOpacity="0.28"/><stop offset="100%" stopColor="#7c9f88" stopOpacity="0.01"/></linearGradient></defs>{[0,.25,.5,.75,1].map(t=><g key={t}><line x1={left} x2={w-10} y1={y(max*t)} y2={y(max*t)} stroke="#e9ece8" strokeDasharray="3 4"/><text x={left-12} y={y(max*t)+4} textAnchor="end">{max>=1000?`${(max*t/1000).toFixed(0)}k`:num(max*t)}</text></g>)}<path d={area} fill="url(#chartFill)"/><path d={line} fill="none" stroke="#668d73" strokeWidth="2.4" strokeLinejoin="round"/>{labels.map((label,i)=>(i===0||i===labels.length-1||i%Math.max(1,Math.floor(labels.length/5))===0)&&<text key={i} x={x(i)} y={h-5} textAnchor="middle">{label}</text>)}{data.map((v,i)=><rect key={i} x={x(i)-10} y={top} width={Math.max(20,(w-left)/data.length)} height={h-top-bottom} fill="transparent" onMouseEnter={()=>setHover(i)}/>)}{hover!==null&&<g><line x1={x(hover)} x2={x(hover)} y1={top} y2={h-bottom} stroke="#b5c7bc"/><circle cx={x(hover)} cy={y(data[hover])} r="4" fill="#315e45"/><rect x={Math.min(w-140,Math.max(left,x(hover)-65))} y="5" width="130" height="24" rx="6" fill="#173e31"/><text x={Math.min(w-75,Math.max(left+65,x(hover)))} y="21" textAnchor="middle" fill="white" style={{fill:'white'}}>{labels[hover]} · {num(data[hover])}</text></g>}</svg></div>}

createRoot(document.getElementById('root')!).render(<App/>);
